head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[accordion > P > unCollapseAll]<br/>Accordion 컴포넌트의 초기 렌더링 시 모든 패널을 펼칠지 설정합니다.",
    "validation" : [
        "unCollapseAll=true 설정 시 초기 렌더링에서 모든 패널이 펼친 상태로 렌더링됩니다.",
        "unCollapseAll=true 설정 시 비활성화(disabled) 상태인 패널은 펼치는 대상에서 제외됩니다.",
        "unCollapseAll=true 이면 selectedPanel 속성은 무시되어 selectedPanel 로 지정한 패널만 열리는 것이 아니라 모든 비-disabled 패널이 열립니다.",
        "collapseAll=true 이면 unCollapseAll 속성은 무시되어 패널이 모두 열리지 않습니다.",
        "unCollapseAll=false (default) 설정 시 패널의 초기 열림/닫힘 상태가 selectedPanel 속성에 의해 결정됩니다.",
        "unCollapseAll=true 이고 independentPanel=false 이면 초기에는 패널이 모두 열려 있지만, 패널 클릭 시 상호 배타 동작이 적용됩니다.",
        "unCollapseAll 속성을 생략하면 기본값 false 로 동작합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정
    let properties = {
        unCollapseAll : con_unCollapseAll.getText(),
        collapseAll : con_collapseAll.getText(),
        selectedPanel : con_selectedPanel.getValue(),
        independentPanel : con_independentPanel.getText(),
    };

    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    $c.gcm.createLabel('label="* unCollapseAll=true : 비-disabled 모든 패널이 초기 펼침 상태 (panels1 은 disabledPanels=true 로 고정되어 unCollapseAll=true 라도 닫힘)"', '', 'label1');
    $c.gcm.createLabel('label="* unCollapseAll=true + selectedPanel=panels2 : selectedPanel 무시되어 panels2 만 열리지 않고 모든 비-disabled 패널(panels2, panels3) 이 열림"', '', 'label2');
    $c.gcm.createLabel('label="* collapseAll=true + unCollapseAll=true : collapseAll 우선 → unCollapseAll 무시되어 모든 패널 닫힘"', '', 'label3');
    $c.gcm.createLabel('label="* unCollapseAll=false (default) + selectedPanel=panels3 : selectedPanel 로 지정한 panels3 만 열린 상태"', '', 'label4');
    $c.gcm.createLabel('label="* unCollapseAll=true + independentPanel=false : 초기에는 모두 펼침, 사용자가 패널 타이틀 클릭 시 상호 배타 동작 → 다른 열린 패널은 닫힘"', '', 'label5');

    strTarget += '<w2:accordion ' + strNameSpace + ' ' + cList + ' id="" style="width:240px; height:320px;">';
    strTarget += '<w2:panels style="" id="panels1" class="" disabledPanels="true">';
    strTarget += '<w2:panelTitle style="" id="panelTitle1" label="panelTitle1 (disabled)"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent1">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel1"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '<w2:panels style="" id="panels2" class="">';
    strTarget += '<w2:panelTitle style="" id="panelTitle2" label="panelTitle2"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent2">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel2"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '<w2:panels style="" id="panels3" class="">';
    strTarget += '<w2:panelTitle style="" id="panelTitle3" label="panelTitle3"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent3">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel3"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '</w2:accordion>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "accordion",
        strTarget,
        grp_comp
    );
}



// 현재 열린 패널 정보 출력 (getOpenPanelListInfo)
scwin.btn_getOpenPanel_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("===== getOpenPanelListInfo() 결과 =====");
    let openList = target1.getOpenPanelListInfo();
    wf_body_bottom.getObj("scwin").setReturnValue("열린 패널 수 : " + (openList ? openList.length : 0));
    if (openList && openList.length > 0) {
        for (let i = 0; i < openList.length; i++) {
            wf_body_bottom.getObj("scwin").setReturnValue("열린 패널[" + i + "] id : " + openList[i].id);
        }
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("열린 패널 없음 (모두 닫힘)");
    }
};
